def _piece(client, fake, seed=1, n=1):
    fake.replies.append(analysis(*[garment((0.0, i / n, 1.0, (i + 1) / n)) for i in range(n)]))
    r = client.post("/api/ingest", files=[("files", (f"p{seed}.jpg", noise_image_bytes(seed), "image/jpeg"))])
    assert r.status_code == 201, r.text
    client.app.state.worker.drain()
    pieces = client.get("/api/ingest/pieces").json()
    return pieces[0] if n == 1 else pieces


def _data(client):
    return client.app.state.ctx.data_dir


def _exists(client, rel):
    return (_data(client) / rel).is_file()


def test_settings_say_when_clean_pictures_are_available(oa, client):
    assert oa.get("/api/settings").json()["clean_pictures"] is True
    assert oa.get("/api/settings").json()["auto_clean_pictures"] is False  # the fixture writes auto off
    assert client.get("/api/settings").json()["clean_pictures"] is False  # the default fixture is Anthropic


def test_ui_chosen_openai_also_enables_clean_pictures(tmp_path):
    from kyapehnu.agent.llm import store

    saved = store.LlmStore(active="openai", providers={"openai": store.ProviderSecret(api_key="k", model="m")})
    s = Settings(_env_file=None, data_dir=tmp_path, config_file=tmp_path / "missing.yaml")
    s.__pydantic_fields_set__.difference_update(llm.ENV_FIELDS)  # as if nothing were set in the environment

    assert llm.image_model(llm.resolve(s, saved)) == IMAGE_MODEL
    assert llm.image_model(llm.resolve(s, store.LlmStore())) is None


def test_generate_keeps_the_original_shown_and_stores_the_clean_picture_beside_it(oa, fake):
    piece = _piece(oa, fake)
    original = (_data(oa) / piece["cutout_path"]).read_bytes()
    fake.edits.append(cutout_with_transparency())

    r = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")

    assert r.status_code == 200, r.text
    body = r.json()
    assert (body["cutout_path"], body["thumb_path"], body["picture_generated"]) == (
        piece["cutout_path"],
        piece["thumb_path"],
        False,
    )
    assert _exists(oa, body["alt_cutout_path"]) and _exists(oa, body["alt_thumb_path"])
    assert body["alt_cutout_path"] != piece["cutout_path"]
    call = fake.edit_calls[0]
    assert call["model"] == IMAGE_MODEL and "colour" in call["prompt"]
    sent = Image.open(io.BytesIO(call["image"]))
    # the photo crop itself, not the cutout: the cutout model can eat white fabric on a light backdrop
    assert sent.mode == "RGB" and sent.size == Image.open(io.BytesIO(original)).size
    assert oa.get(f"/{body['alt_thumb_path']}").status_code == 200
    logged = oa.get("/api/debug/llm-calls", params={"purpose": "clean_picture"}).json()
    assert len(logged) == 1 and logged[0]["model"] == IMAGE_MODEL and logged[0]["error"] is None


def test_the_request_names_the_item_so_other_clothing_and_the_person_are_left_out(oa, fake):
    fake.replies.append(analysis(garment(name="Olive denim jacket", category="outerwear"), photo_type="worn"))
    oa.post("/api/ingest", files=[("files", ("worn.jpg", noise_image_bytes(9), "image/jpeg"))])
    oa.app.state.worker.drain()
    [piece] = oa.get("/api/ingest/pieces").json()
    fake.edits += [cutout_with_transparency(), cutout_with_transparency()]

    oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")
    item = oa.post(f"/api/ingest/pieces/{piece['id']}/accept", json={"overrides": {"name": "My jacket"}}).json()
    oa.post(f"/api/items/{item['id']}/clean-picture")

    piece_prompt, item_prompt = (c["prompt"] for c in fake.edit_calls)
    assert "Olive denim jacket" in piece_prompt and "outerwear" in piece_prompt
    assert "My jacket" in item_prompt  # an item uses the name the person gave it
    for prompt in (piece_prompt, item_prompt):
        assert "person" in prompt and "other clothing" in prompt.lower()
        assert "long sleeves stay full length" in prompt  # removing the arms must not take the sleeves


def test_footwear_prompt_keeps_the_sole_and_skips_the_mannequin():
    piece = IngestPiece(
        user_id=1, proposed_tags={"name": "Red Dunk Low", "category": "footwear", "subcategory": "sneakers"}
    )
    prompt, _ = pictures._prompt(piece)
    assert "sneakers" in prompt and "no spikes, studs, cleats" in prompt
    assert "toe pointing left" in prompt  # one pose for every shoe, so the shelf lines up
    assert "mannequin" not in prompt and "sleeves" not in prompt


@pytest.mark.parametrize(
    ("category", "subcategory", "name", "phrase"),
    [
        ("ethnic", "saree", "Silk saree", "neatly folded"),
        ("ethnic", "dupatta", "Pink dupatta", "neatly folded"),
        ("ethnic", "kurti", "Coral kurti", "invisible mannequin"),
        ("accessory", "stole", "Wool stole", "invisible mannequin"),
        ("accessory", "earrings", "Jhumkas", "the pair side by side"),
        ("accessory", "necklace", "Choker", "smooth oval"),
        ("accessory", "ring", "Ruby ring", "standing upright, seen from the front"),
        ("accessory", "bangles", "Glass bangles", "standing upright side by side"),
        ("accessory", "maang tikka", "Kundan tikka", "laid flat on its own"),
        ("accessory", "watch", "Steel watch", "invisible mannequin"),
        ("top", "top", "Ring-neck top", "invisible mannequin"),
        ("ethnic", "blouse", "Red saree blouse", "invisible mannequin"),
    ],
)
def test_the_view_follows_the_kind(category, subcategory, name, phrase):
    piece = IngestPiece(user_id=1, proposed_tags={"name": name, "category": category, "subcategory": subcategory})

    prompt, _ = pictures._prompt(piece)

    assert phrase in prompt
    if category == "accessory" and phrase != "invisible mannequin":
        assert "no ear, neck, hand, wrist" in prompt and "mannequin" not in prompt


def test_caps_are_drawn_from_above_and_sunglasses_from_the_side():
    cap = IngestPiece(user_id=1, proposed_tags={"name": "Navy NY cap", "category": "accessory", "subcategory": "cap"})
    shades = IngestPiece(
        user_id=1, proposed_tags={"name": "Black aviators", "category": "accessory", "subcategory": "sunglasses"}
    )
    watch = IngestPiece(user_id=1, proposed_tags={"name": "Steel watch", "category": "accessory"})
    (cap_prompt, _), (shades_prompt, _), (watch_prompt, _) = map(pictures._prompt, (cap, shades, watch))
    assert "directly above" in cap_prompt and "mannequin" not in cap_prompt
    assert "side profile" in shades_prompt and "lens on the left" in shades_prompt
    assert "directly above" not in watch_prompt and "lens on the left" not in watch_prompt


def test_switch_shows_the_clean_picture_and_switches_back(oa, fake):
    piece = _piece(oa, fake)
    fake.edits.append(cutout_with_transparency())
    made = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()

    shown = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch").json()
    back = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch").json()

    assert (shown["cutout_path"], shown["alt_cutout_path"], shown["picture_generated"]) == (
        made["alt_cutout_path"],
        piece["cutout_path"],
        True,
    )
    assert (shown["thumb_path"], shown["alt_thumb_path"]) == (made["alt_thumb_path"], piece["thumb_path"])
    assert (back["cutout_path"], back["alt_cutout_path"], back["picture_generated"]) == (
        piece["cutout_path"],
        made["alt_cutout_path"],
        False,
    )


def test_switch_or_delete_without_a_clean_picture_is_a_conflict(oa, fake):
    piece = _piece(oa, fake)

    assert oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch").status_code == 409
    assert oa.delete(f"/api/ingest/pieces/{piece['id']}/clean-picture").status_code == 409


def test_delete_brings_the_original_back_and_removes_the_generated_files(oa, fake):
    piece = _piece(oa, fake)
    fake.edits.append(cutout_with_transparency())
    made = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()
    oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch")

    after = oa.delete(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()

    assert (after["cutout_path"], after["thumb_path"]) == (piece["cutout_path"], piece["thumb_path"])
    assert (after["alt_cutout_path"], after["alt_thumb_path"], after["picture_generated"]) == (None, None, False)
    assert not _exists(oa, made["alt_cutout_path"]) and not _exists(oa, made["alt_thumb_path"])
    assert _exists(oa, piece["cutout_path"]) and _exists(oa, piece["thumb_path"])


def test_generating_again_replaces_the_previous_clean_picture_and_never_the_original(oa, fake):
    piece = _piece(oa, fake)
    fake.edits += [cutout_with_transparency(), cutout_with_transparency()]
    first = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()
    oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch")  # the clean picture is the one shown

    second = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()

    assert (second["cutout_path"], second["picture_generated"]) == (piece["cutout_path"], False)
    assert second["alt_cutout_path"] not in (first["alt_cutout_path"], piece["cutout_path"])
    assert not _exists(oa, first["alt_cutout_path"]) and not _exists(oa, first["alt_thumb_path"])
    assert _exists(oa, piece["cutout_path"])
    assert fake.edit_calls[1]["image"] == fake.edit_calls[0]["image"]  # always generated from the original


def test_an_opaque_result_gets_its_background_removed_locally(oa, fake, monkeypatch):
    piece = _piece(oa, fake)
    seen = []
    monkeypatch.setattr(images, "remove_background", lambda im: seen.append(im.mode) or im.convert("RGBA"))
    fake.edits.append(png((255, 255, 255, 255)))

    assert oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").status_code == 200
    assert seen == ["RGB"]


def test_a_transparent_result_is_kept_as_it_is(oa, fake, monkeypatch):
    piece = _piece(oa, fake)
    monkeypatch.setattr(images, "remove_background", lambda im: pytest.fail("must not run"))
    fake.edits.append(cutout_with_transparency())

    assert oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").status_code == 200


@pytest.mark.parametrize(
    "result",
    [LLMUnavailableError(f"400 unknown model, key {OPENAI_KEY}"), LLMOutputError("no image"), b"not a picture"],
)
def test_a_failed_generation_changes_nothing_and_never_echoes_the_key(oa, fake, result):
    piece = _piece(oa, fake)
    files_before = stored_files(_data(oa), "cutout")
    fake.edits.append(result)

    r = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")

    assert r.status_code == 502 and r.json()["code"] == "provider_error"
    assert OPENAI_KEY not in r.text
    assert stored_files(_data(oa), "cutout") == files_before
    assert oa.get("/api/ingest/pieces").json()[0]["alt_cutout_path"] is None


def test_other_providers_cannot_generate(client, fake):
    piece = _piece(client, fake)

    r = client.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")

    assert r.status_code == 409 and "OpenAI" in r.json()["detail"] and fake.edit_calls == []


def test_accepting_a_piece_carries_both_pictures_to_the_item(oa, fake):
    piece = _piece(oa, fake)
    fake.edits.append(cutout_with_transparency())
    oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")
    shown = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch").json()

    item = oa.post(f"/api/ingest/pieces/{piece['id']}/accept", json={}).json()

    assert (item["cutout_path"], item["alt_cutout_path"], item["picture_generated"]) == (
        shown["cutout_path"],
        piece["cutout_path"],
        True,
    )
    assert oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").status_code == 409  # no longer in review


def test_item_pictures_can_be_generated_switched_and_deleted(oa, fake):
    piece = _piece(oa, fake)
    item = oa.post(f"/api/ingest/pieces/{piece['id']}/accept", json={}).json()
    fake.edits.append(cutout_with_transparency())

    made = oa.post(f"/api/items/{item['id']}/clean-picture").json()
    shown = oa.post(f"/api/items/{item['id']}/clean-picture/switch").json()
    after = oa.delete(f"/api/items/{item['id']}/clean-picture").json()

    assert made["alt_cutout_path"] and made["cutout_path"] == item["cutout_path"]
    assert shown["cutout_path"] == made["alt_cutout_path"] and shown["picture_generated"] is True
    assert (after["cutout_path"], after["alt_cutout_path"], after["picture_generated"]) == (
        item["cutout_path"],
        None,
        False,
    )
    assert not _exists(oa, made["alt_cutout_path"])
    with Session(oa.app.state.ctx.engine) as s:  # the accepted piece never points at a removed file
        p = s.get(IngestPiece, piece["id"])
        assert (p.cutout_path, p.thumb_path, p.alt_cutout_path, p.picture_generated) == (
            item["cutout_path"],
            item["thumb_path"],
            None,
            False,
        )


def test_permanent_delete_removes_both_pictures(oa, fake):
    piece = _piece(oa, fake)
    fake.edits.append(cutout_with_transparency())
    oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")
    item = oa.post(f"/api/ingest/pieces/{piece['id']}/accept", json={}).json()

    assert oa.delete(f"/api/items/{item['id']}", params={"hard": True}).status_code == 204

    for rel in (item["cutout_path"], item["thumb_path"], item["alt_cutout_path"], item["alt_thumb_path"]):
        assert not _exists(oa, rel)


def test_startup_cleanup_never_sweeps_the_second_picture(oa, fake):
    piece = _piece(oa, fake)
    fake.edits.append(cutout_with_transparency())
    made = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture").json()
    old = 1_000_000_000
    for rel in (made["alt_cutout_path"], made["alt_thumb_path"]):
        os.utime(_data(oa) / rel, (old, old))

    housekeeping.sweep_orphans(oa.app.state.ctx.engine, oa.app.state.ctx.files, DEFAULT_SWEEP_MAX_DELETES)

    assert _exists(oa, made["alt_cutout_path"]) and _exists(oa, made["alt_thumb_path"])


def test_merging_pieces_drops_their_clean_pictures(oa, fake):
    a, b = _piece(oa, fake, n=2)
    fake.edits.append(cutout_with_transparency())
    made = oa.post(f"/api/ingest/pieces/{a['id']}/clean-picture").json()
    oa.post(f"/api/ingest/pieces/{a['id']}/clean-picture/switch")

    merged = oa.post(f"/api/ingest/pieces/{a['id']}/merge", json={"other_piece_ids": [b["id"]]}).json()

    assert (merged["alt_cutout_path"], merged["alt_thumb_path"], merged["picture_generated"]) == (None, None, False)
    assert not _exists(oa, made["alt_cutout_path"]) and _exists(oa, merged["cutout_path"])


def test_existing_rows_upgrade_with_no_second_picture(oa, fake):
    piece = _piece(oa, fake)
    item = oa.post(f"/api/ingest/pieces/{piece['id']}/accept", json={}).json()

    with Session(oa.app.state.ctx.engine) as s:
        row = s.get(Item, item["id"])
        assert (row.alt_cutout_path, row.alt_thumb_path, row.picture_generated) == (None, None, False)


# --- automatic clean pictures on upload ----------------------------------------------------------------------


def test_automatic_clean_pictures_are_on_by_default():
    from kyapehnu.core.config import Prefs

    assert Prefs().ingest.auto_clean_pictures is True


def test_upload_makes_a_clean_picture_of_every_garment_and_shows_it(oa_auto, fake):
    import time

    fake.edits += [cutout_with_transparency(), cutout_with_transparency()]
    start = time.perf_counter()

    pieces = _piece(oa_auto, fake, n=2)

    assert time.perf_counter() - start < 4  # no call waits on a database lock
    assert len(fake.edit_calls) == 2 and all(c["model"] == IMAGE_MODEL for c in fake.edit_calls)
    for piece, call in zip(pieces, fake.edit_calls, strict=True):
        assert piece["picture_generated"] is True and piece["state"] == "pending_review"
        assert _exists(oa_auto, piece["cutout_path"]) and _exists(oa_auto, piece["alt_cutout_path"])
        sent, crop = (
            Image.open(io.BytesIO(b)) for b in (call["image"], (_data(oa_auto) / piece["alt_cutout_path"]).read_bytes())
        )
        assert sent.size == crop.size  # made from the real crop
    job = oa_auto.get("/api/ingest/jobs").json()[0]
    assert (job["status"], job["processed"], job["failed"]) == ("done", 1, 0)
    logged = oa_auto.get("/api/debug/llm-calls", params={"purpose": "clean_picture"}).json()
    assert len(logged) == 2 and all(row["error"] is None for row in logged)


def test_a_failed_automatic_picture_keeps_the_original_and_never_fails_the_photo(oa_auto, fake):
    fake.edits += [LLMUnavailableError("429 slow down"), cutout_with_transparency()]

    first, second = _piece(oa_auto, fake, n=2)

    assert (first["picture_generated"], first["alt_cutout_path"]) == (False, None)
    assert _exists(oa_auto, first["cutout_path"]) and second["picture_generated"] is True
    job = oa_auto.get("/api/ingest/jobs").json()[0]
    assert (job["status"], job["failed"]) == ("done", 0)


def test_an_unexpected_error_while_making_pictures_never_fails_the_photo(oa_auto, fake):
    piece = _piece(oa_auto, fake)  # no scripted picture: the fake raises AssertionError

    assert (piece["state"], piece["picture_generated"]) == ("pending_review", False)
    assert oa_auto.get("/api/ingest/jobs").json()[0]["status"] == "done"


def test_no_automatic_pictures_when_switched_off_or_with_another_provider(oa, client, fake):
    _piece(oa, fake)
    _piece(client, fake, seed=2)

    assert fake.edit_calls == []


def test_the_original_can_still_be_shown_after_an_automatic_clean_picture(oa_auto, fake):
    fake.edits.append(cutout_with_transparency())
    piece = _piece(oa_auto, fake)

    back = oa_auto.post(f"/api/ingest/pieces/{piece['id']}/clean-picture/switch").json()

    assert (back["cutout_path"], back["picture_generated"]) == (piece["alt_cutout_path"], False)


def test_a_piece_accepted_while_its_picture_is_being_made_is_left_alone(oa, fake):
    from kyapehnu.wardrobe.ingest import review

    piece = _piece(oa, fake)
    files_before = stored_files(_data(oa), "cutout")

    def accept_meanwhile():
        with Session(oa.app.state.ctx.engine) as s:
            review.accept_piece(s, s.get(IngestPiece, piece["id"]))
        return cutout_with_transparency()

    fake.edits.append(accept_meanwhile)

    r = oa.post(f"/api/ingest/pieces/{piece['id']}/clean-picture")

    assert r.status_code == 409
    assert stored_files(_data(oa), "cutout") == files_before  # the late picture is not left lying around
    [item] = oa.get("/api/items").json()
    assert (item["cutout_path"], item["alt_cutout_path"]) == (piece["cutout_path"], None)


# --- the OpenAI transport ------------------------------------------------------------------------------------


def _image_response(data: bytes | None):
    import base64

    items = [SimpleNamespace(b64_json=base64.b64encode(data).decode())] if data is not None else []
    return SimpleNamespace(data=items)


def _bad_request(message: str) -> openai.BadRequestError:
    response = httpx.Response(400, request=httpx.Request("POST", "http://test/v1/images/edits"))
    return openai.BadRequestError(message, response=response, body=None)


def test_edit_image_asks_for_a_transparent_png_and_decodes_the_result():
    seen = {}

    def edit(**kw):
        seen.update(kw)
        return _image_response(b"PNG-BYTES")

    t = OpenAICompatTransport("u", "k", "m", client=SimpleNamespace(images=SimpleNamespace(edit=edit)))

    assert t.edit_image(image=b"SRC", prompt="p", model=IMAGE_MODEL) == b"PNG-BYTES"
    assert (seen["model"], seen["prompt"], seen["background"], seen["output_format"]) == (
        IMAGE_MODEL,
        "p",
        "transparent",
        "png",
    )
    assert seen["image"][1] == b"SRC"


def test_edit_image_retries_with_plain_options_when_the_model_rejects_the_extras():
    calls = []

    def edit(**kw):
        calls.append(sorted(kw))
        if "background" in kw:
            raise _bad_request("Unknown parameter: 'background'")
        return _image_response(b"PNG-BYTES")

    t = OpenAICompatTransport("u", "k", "m", client=SimpleNamespace(images=SimpleNamespace(edit=edit)))

    assert t.edit_image(image=b"SRC", prompt="p", model=IMAGE_MODEL) == b"PNG-BYTES"
    assert calls[1] == ["image", "model", "prompt"]


def test_edit_image_failures_are_typed():
    def refuse(**kw):
        raise _bad_request("The model does not exist")

    refusing = OpenAICompatTransport("u", "k", "m", client=SimpleNamespace(images=SimpleNamespace(edit=refuse)))
    empty = OpenAICompatTransport(
        "u", "k", "m", client=SimpleNamespace(images=SimpleNamespace(edit=lambda **kw: _image_response(None)))
    )

    with pytest.raises(LLMUnavailableError, match="does not exist"):
        refusing.edit_image(image=b"SRC", prompt="p", model=IMAGE_MODEL)
    with pytest.raises(LLMOutputError):
        empty.edit_image(image=b"SRC", prompt="p", model=IMAGE_MODEL)


def test_a_provider_without_image_generation_says_so():
    class TextOnly:
        provider, model = "text-only", "t-1"

    with pytest.raises(LLMUnavailableError, match="cannot generate pictures"):
        LLMProvider(TextOnly()).edit_image(
            image=b"x", prompt="p", model=IMAGE_MODEL, purpose="clean_picture", user_id=OWNER_ID
        )


def test_image_generation_log_never_stores_an_echoed_key():
    logs = []
    t = FakeTransport()
    t.api_key = OPENAI_KEY
    t.edits.append(LLMUnavailableError(f"401 bad key {OPENAI_KEY}"))

    with pytest.raises(LLMUnavailableError):
        LLMProvider(t, log=logs.append).edit_image(
            image=b"x", prompt="p", model=IMAGE_MODEL, purpose="clean_picture", user_id=OWNER_ID
        )

    assert OPENAI_KEY not in logs[0].error and logs[0].model == IMAGE_MODEL and logs[0].purpose == "clean_picture"


