@pytest.fixture
def stored_piece(engine, store, tmp_path, openai_settings):
    """A piece of an uploaded photo on `store`, and what is needed to make its clean picture."""
    import io

    from kyapehnu.wardrobe.ingest import pipeline
    from tests.ingest_store_helpers import make_store_ctx

    with Session(engine) as s:
        ensure_owner(s)
        s.commit()
    ctx = make_store_ctx(engine, store, tmp_path, [analysis(garment())])
    with Session(engine) as s:
        job = pipeline.create_upload_job(OWNER_ID, s, ctx.files, [("a.jpg", io.BytesIO(noise_image_bytes(1)))])
        job_id = job.id
    pipeline.run_job(OWNER_ID, ctx, job_id)
    with Session(engine) as s:
        piece_id = s.exec(select(IngestPiece.id)).one()
    ctx.provider.transport.edits.append(cutout_with_transparency())
    return ctx, openai_settings, piece_id


def _keys(store) -> set[str]:
    return {f.key for f in store.list("images/")}


def test_removing_the_clean_picture_deletes_its_keys_and_keeps_the_original_on_every_store(stored_piece, store):
    from kyapehnu.wardrobe import pictures

    ctx, settings, piece_id = stored_piece
    with Session(ctx.engine) as s:
        piece = s.get(IngestPiece, piece_id)
        shown_before = (piece.cutout_path, piece.thumb_path)
        original = set(shown_before)
        pictures.generate(ctx, settings, s, piece, show=True)
        clean = {piece.cutout_path, piece.thumb_path}
        assert clean.isdisjoint(original) and clean <= _keys(store)

        pictures.remove(ctx, s, piece)

        assert (piece.cutout_path, piece.thumb_path) == shown_before
        assert piece.alt_cutout_path is None and piece.alt_thumb_path is None
    keys = _keys(store)
    assert original <= keys
    assert clean.isdisjoint(keys)  # the clean picture's keys are gone from the store, not just from the row


def test_replacing_the_clean_picture_deletes_the_previous_keys_on_every_store(stored_piece, store):
    from kyapehnu.wardrobe import pictures

    ctx, settings, piece_id = stored_piece
    ctx.provider.transport.edits.append(cutout_with_transparency())
    with Session(ctx.engine) as s:
        piece = s.get(IngestPiece, piece_id)
        pictures.generate(ctx, settings, s, piece)
        first = {piece.alt_cutout_path, piece.alt_thumb_path}

        pictures.generate(ctx, settings, s, piece)

        second = {piece.alt_cutout_path, piece.alt_thumb_path}
    assert first.isdisjoint(second)
    assert second <= _keys(store) and first.isdisjoint(_keys(store))


def test_the_backdrop_is_furthest_from_the_garment_and_is_cut_out_without_eating_light_or_dark_fabric():
    assert pictures._key([(30, 160, 70)]) != "green"  # a green garment is not asked for on green
    shirt = Image.new("RGB", (60, 80), pictures.KEYS["magenta"])
    shirt.paste((239, 234, 224), (10, 10, 50, 40))  # cream, as light as the backdrop is bright
    shirt.paste((1, 2, 4), (10, 40, 50, 70))  # near-black seam shadow
    cut = pictures._key_out(shirt, "magenta")
    assert cut is not None
    alpha = cut.getchannel("A")
    assert alpha.getpixel((2, 2)) == 0 and alpha.getpixel((30, 25)) == alpha.getpixel((30, 55)) == 255
    assert pictures._key_out(Image.new("RGB", (60, 80), (120, 120, 120)), "magenta") is None  # backdrop ignored


def test_thumbs_are_trimmed_to_the_garment_so_every_piece_shows_at_the_same_scale():
    picture = Image.new("RGBA", (400, 400), (0, 0, 0, 0))
    picture.paste((20, 30, 60, 255), (150, 150, 250, 250))  # a 100px garment in a wide transparent border
    thumb = Image.open(io.BytesIO(images.thumb_bytes(picture)))
    assert thumb.size == (108, 108)  # the garment and a 4% margin on each side
    flat = Image.new("RGB", (300, 200), (200, 200, 200))
    assert images.trim(flat) is flat  # no transparency: nothing to trim


def test_retrim_remakes_old_thumbs_from_their_cutouts_and_keeps_their_keys(oa, fake):
    engine, store = oa.app.state.ctx.engine, oa.app.state.ctx.files
    piece = _piece(oa, fake)
    before = store.read_bytes(piece["thumb_path"])
    bordered = Image.new("RGBA", (400, 400), (0, 0, 0, 0))
    bordered.paste((20, 30, 60, 255), (150, 150, 250, 250))
    buf = io.BytesIO()
    bordered.save(buf, "PNG")
    store.put(piece["cutout_path"], buf.getvalue())

    assert pictures.retrim_thumbs(engine, store) >= 1
    after = store.read_bytes(piece["thumb_path"])
    assert after != before and Image.open(io.BytesIO(after)).size == (108, 108)


def test_backdrop_enclosed_by_the_item_is_keyed_out_too():
    """A ring, a necklace or a bag handle encloses backdrop the border flood-fill cannot reach."""
    green = pictures.KEYS["green"]
    im = Image.new("RGB", (60, 60), green)
    draw = __import__("PIL.ImageDraw", fromlist=["ImageDraw"]).Draw(im)
    draw.ellipse((10, 10, 50, 50), fill=(200, 160, 40))  # a gold disc
    draw.ellipse((22, 22, 38, 38), fill=green)  # with a hole of backdrop in the middle

    out = pictures._key_out(im, "green", holes=True)

    assert out is not None
    alpha = out.getchannel("A")
    assert alpha.getpixel((2, 2)) == 0 and alpha.getpixel((30, 30)) == 0  # outside and the hole: gone
    assert alpha.getpixel((15, 30)) == 255  # the gold stays


def test_a_garment_keeps_an_accent_of_the_backdrop_colour():
    """A tee's logo may be the very blue the backdrop was asked for: only an accessory's holes are keyed inside."""
    blue = pictures.KEYS["blue"]
    im = Image.new("RGB", (60, 60), blue)
    draw = __import__("PIL.ImageDraw", fromlist=["ImageDraw"]).Draw(im)
    draw.rectangle((10, 10, 50, 50), fill=(200, 30, 30))  # a red tee
    draw.rectangle((25, 25, 35, 35), fill=blue)  # with a blue logo

    out = pictures._key_out(im, "blue")

    assert out is not None
    alpha = out.getchannel("A")
    assert alpha.getpixel((2, 2)) == 0 and alpha.getpixel((30, 30)) == 255
